import sys
from collections import defaultdict, deque

MOD = 10**9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def euler_totient(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def modinv(a, m):
    return pow(a, m - 2, m)

n = int(input())
a = list(map(int, input().split()))
edges = [list(map(int, input().split())) for _ in range(n - 1)]

# Build the tree
tree = defaultdict(list)
for x, y in edges:
    tree[x].append(y)
    tree[y].append(x)

# Precompute Euler's totient function for all numbers up to n
phi = [0] * (n + 1)
for i in range(1, n + 1):
    phi[i] = euler_totient(i)

# Compute shortest distances using BFS
def bfs(start):
    dist = [-1] * (n + 1)
    queue = deque([start])
    dist[start] = 0
    while queue:
        u = queue.popleft()
        for v in tree[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

# Calculate the expected value
expected_value = 0
for u in range(1, n + 1):
    dist_u = bfs(u)
    for v in range(1, n + 1):
        if u != v:
            f_uv = phi[a[u - 1] * a[v - 1]] * dist_u[v]
            expected_value += f_uv
            expected_value %= MOD

# Calculate the modular inverse of n(n - 1)
inv_n_n_minus_1 = modinv(n * (n - 1), MOD)

# Output the result
result = (expected_value * inv_n_n_minus_1) % MOD
print(result)
